<?php
ownerOnly();
$q=$pdo->prepare('SELECT nombre,estado_suscripcion,activo,proximo_mantenimiento FROM negocios WHERE id=?');$q->execute([(int)me()['store_id']]);$negocio=$q->fetch();
$q=$pdo->prepare('SELECT id,importe,referencia,metodo,fecha_pago,estado,fecha_verificacion FROM pagos WHERE id_negocio=? ORDER BY id DESC LIMIT 50');
$q->execute([(int)me()['store_id']]);$pagos=$q->fetchAll();
?>
<div class="page-heading"><div><p class="eyebrow">CUENTA DEL NEGOCIO</p><h1>Mi suscripción</h1><p class="muted">Reporta pagos y revisa su verificación por el administrador global.</p></div></div>
<section class="panel"><h2>Estado actual</h2><p><strong><?=h($negocio['nombre'])?></strong> · <span class="pill-estado estado-<?=$negocio['activo']?'verde':'rojo'?>"><?=h(str_replace('_',' ',ucfirst($negocio['estado_suscripcion'])))?></span></p><p class="muted">Próximo mantenimiento: <?=h($negocio['proximo_mantenimiento']??'Sin fecha programada')?></p></section>
<section class="panel"><h2>Notificar un pago</h2><p class="muted">Esto solo genera una solicitud. No realiza un cobro ni confirma automáticamente un depósito.</p><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="enviar_pago"><div><label>Importe (MXN)</label><input type="number" min="0.01" max="9999999" step="0.01" name="importe" required></div><div><label>Referencia</label><input name="referencia" minlength="5" maxlength="80" required placeholder="Número o concepto identificador"></div><div><label>Método de pago</label><select name="metodo"><option value="transferencia">Transferencia</option><option value="efectivo">Efectivo</option><option value="otro">Otro</option></select></div><div><label>Fecha de pago</label><input type="date" name="fecha_pago" max="<?=date('Y-m-d')?>" required></div><div class="span-2"><button class="btn primary">Enviar para verificación</button></div></form></section>
<section class="panel"><h2>Historial de pagos reportados</h2><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Importe</th><th>Referencia</th><th>Método</th><th>Estado</th></tr></thead><tbody><?php foreach($pagos as $p):?><tr><td><?=h($p['fecha_pago'])?></td><td>$<?=number_format((float)$p['importe'],2)?></td><td><?=h($p['referencia'])?></td><td><?=h(ucfirst($p['metodo']))?></td><td><span class="pill-estado estado-<?=$p['estado']==='verificado'?'verde':($p['estado']==='rechazado'?'rojo':'amarillo')?>"><?=h(ucfirst($p['estado']))?></span></td></tr><?php endforeach; ?><?php if(!$pagos):?><tr><td colspan="5">Aún no hay pagos reportados.</td></tr><?php endif; ?></tbody></table></div></section>
